1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	};
62	
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	
66	const ALIKE_BLOCK_SIZE = 3;
67	const ALIKE_BLOCK_PREMIUM = 60;
68	
69	type AlikeGroup = [type: string, count: number];
70	
71	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
72	  const countByType = new Map<string, number>();
73	
74	  for (const item of items) {
75	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
76	  }
77	
78	  return [...countByType];
79	};
80	
81	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
82	
83	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
84	
85	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
86	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
87	
88	  return count * basePremiumOfType(type);
89	};
90	
91	/**
92	 * The policy base premium: the sum of the item base premiums, with the
93	 * alike-block discount applied. Policy-scope modifiers are percentages OF
94	 * THIS amount — never of a total that already includes item surcharges.
95	 */
96	const policyBasePremiumOf = (items: Item[]): number =>
97	  groupAlikeItems(items)
98	    .map(basePremiumOfGroup)
99	    .reduce((total, groupPremium) => total + groupPremium, 0);
100	
101	/**
102	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
103	 * premium, independent of the policy base and of the alike-block discount.
104	 */
105	const isCursed = (item: Item): boolean => item.cursed === true;
106	
107	const isHighlyEnchanted = (item: Item): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
109	
110	const itemSurchargeRateOf = (item: Item): number =>
111	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
112	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
113	
114	const itemSurchargesOf = (items: Item[]): number =>
115	  items.reduce(
116	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
117	    0,
118	  );
119	
120	/**
121	 * Policy-scope modifiers: each is a percentage of the policy base premium.
122	 * Surcharges and discounts are netted into a single rate, so the policy base is
123	 * multiplied exactly once — this keeps the result free of the rounding drift
124	 * that separate discount and surcharge terms would introduce. The netted rate
125	 * (and hence the returned amount) is negative when the discounts outweigh the
126	 * surcharges.
127	 */
128	const isLongStanding = (customer: Customer): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
130	
131	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
132	  FIRST_INSURANCE_SURCHARGE -
133	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
134	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
135	
136	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
137	  policyBase * policyModifierRateOf(policy);
138	
139	const quotePremium = (items: Item[], policy: Policy): number => {
140	  const policyBase = policyBasePremiumOf(items);
141	  const premium =
142	    policyBase +
143	    itemSurchargesOf(items) +
144	    policyModifiersOn(policyBase, policy) +
145	    PROCESSING_FEE;
146	
147	  return Math.ceil(premium);
148	};
149	
150	/**
151	 * Whether any step precedes this one. A quote is a follow-up contract when the
152	 * customer already holds one, and today every step is a quote — so "has a
153	 * predecessor" and "is a follow-up contract" coincide.
154	 *
155	 * They stop coinciding once claim steps exist: a claim at index 0 would make
156	 * the quote at index 1 look like a follow-up. At that point the caller must
157	 * count preceding QUOTE steps instead of asking this. The name is deliberately
158	 * about position, not contracts, so that the substitution is a visible change
159	 * at the call site rather than a silent redefinition here.
160	 */
161	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
162	
163	const insuranceSumOf = (items: Item[]): number =>
164	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
165	
166	const payoutForDamage = (damage: Damage): number =>
167	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
168	
169	const settleClaim = (claim: ClaimStep, steps: Step[]): ClaimResult => {
170	  const policy = steps[claim.policy] as QuoteStep;
171	  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
172	  const payout = claim.incident.damages.reduce(
173	    (total, damage) => total + payoutForDamage(damage),
174	    0,
175	  );
176	
177	  return { payout, remainingCap: cap - payout };
178	};
179	
180	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
181	  results: scenario.steps.map((step, stepIndex) =>
182	    isQuoteStep(step)
183	      ? {
184	          premium: quotePremium(step.items, {
185	            customer: scenario.customer,
186	            isFollowUpContract: hasPrecedingStep(stepIndex),
187	          }),
188	        }
189	      : settleClaim(step, scenario.steps),
190	  ),
191	});
