368	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
369	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
370	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
371	  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remaining cap 0 G");
372	
373	  // --- Claim: multiple items of the same type ---
374	  it.todo("two swords insured, a dragon attack damages both → each damage entry has its own deductible");
375	  it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → rejected");
376	
377	  // --- Errors ---
378	  it.todo("a quote with an unknown item type (broomstick) → rejected with an error");
379	  it.todo("a claim for an item not part of the policy (amulet damaged, only a sword insured) → rejected");
380	  it.todo("a claim with a damage entry of an unknown item type → rejected");
381	  it.todo("a claim with a damage entry of amount -200 → rejected");
382	
383	  // --- CLI ---
384	  it.todo("the CLI reads a JSON scenario from stdin and writes { results } to stdout");
385	  it.todo("the CLI exits with a non-zero status and writes to stderr on an invalid scenario, with no results on stdout");
386	});
